window.HOEREN_TESTS[91] = {"id":"in-der-eisdiele","name":"In der Eisdiele","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Gäste: Willkommen in der Eisdiele Bella. Wir haben eine neue Sorte — Lavendel-Honig, ganz besonders! Probieren Sie sie heute kostenlos. Unsere beliebte Schokolade ist leider gerade aus, kommt aber morgen wieder. Vanille haben wir wie immer. Wir machen alle Sorten frisch und selbst. Lassen Sie es sich schmecken!","gender":"f","q":"Welche Sorte ist neu?","opts":["Schokolade.","Lavendel-Honig.","Vanille."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Pass auf, das Wetter ist herrlich heute! Lass uns ein Eis essen gehen, in der neuen Eisdiele am Markt. Die haben dreißig Sorten, sogar veganes Eis. Treffen wir uns um 16 Uhr? Bring deine Kinder mit, meine kommen auch. Ruf zurück, ich freue mich!","gender":"m","q":"Was schlägt Markus vor?","opts":["Ein Eis essen zu gehen.","Ins Kino zu gehen.","Schwimmen zu gehen."],"correct":0},{"transcript":"Achtung Gäste: Ab Montag haben wir länger geöffnet. Im Sommer bleiben wir bis 22 Uhr offen, nicht mehr nur bis 20 Uhr. So können Sie auch nach dem Abendessen noch ein Eis genießen. Sonntags öffnen wir schon um 11 Uhr. Wir freuen uns auf einen schönen, langen Sommer mit Ihnen!","gender":"m","q":"Bis wann ist die Eisdiele im Sommer offen?","opts":["Bis 22 Uhr.","Bis 20 Uhr.","Bis 24 Uhr."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Ich habe in der Eisdiele gejobbt als Studentin, weißt du noch? Jetzt suchen die wieder eine Aushilfe für den Sommer. Deine Tochter sucht doch einen Ferienjob! Es ist anstrengend, aber man verdient gut und bekommt gratis Eis. Sag ihr Bescheid, bis bald!","gender":"f","q":"Was sucht die Eisdiele?","opts":["Einen Koch.","Einen Lieferanten.","Eine Aushilfe für den Sommer."],"correct":2},{"transcript":"Liebe Gäste: Bei uns bekommen Sie nicht nur Eis im Becher oder in der Waffel. Wir machen auch Eistorten für Geburtstage und Feiern. Bestellen Sie zwei Tage vorher. Auch leckere Milchshakes und Eiskaffee gibt es. Bei diesem heißen Wetter genau das Richtige. Kommen Sie vorbei und kühlen Sie sich ab!","gender":"f","q":"Was kann man für eine Feier bestellen?","opts":["Pizza.","Eistorten.","Kuchen."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer mag was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Viele Leute warten schon. Weißt du was jeder auf dem Zettel will?"},{"speaker":"Lisa","gender":"f","text":"Ich habe gefragt. Fünf Leute wollen Eis und jeder will etwas anderes."},{"speaker":"Lukas","gender":"m","text":"Ich nehme Schokolade. Die dunkle mag ich am liebsten."},{"speaker":"Lisa","gender":"f","text":"Die steht ganz links. Hat jemand nach Mango gefragt?"},{"speaker":"Lukas","gender":"m","text":"Mango will heute keiner. Die haben sie auch nicht mehr."},{"speaker":"Lisa","gender":"f","text":"Ich nehme Erdbeere. Die ist rot und schmeckt nach Sommer."},{"speaker":"Lukas","gender":"m","text":"Die Kinder lieben die auch. Tom bleibt immer bei dem hellen Eis."},{"speaker":"Lisa","gender":"f","text":"Tom nimmt Vanille. Er sagt, dass er nichts anderes will."},{"speaker":"Lukas","gender":"m","text":"Die ist weiß und mild. Fragt jemand nach Haselnuss?"},{"speaker":"Lisa","gender":"f","text":"Haselnuss nimmt auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara mag es lieber frisch und sauer."},{"speaker":"Lisa","gender":"f","text":"Sara nimmt Zitrone. An heißen Tagen findet sie die am besten."},{"speaker":"Lukas","gender":"m","text":"Die ist gelb und kalt. Tim sucht das grüne Eis."},{"speaker":"Lisa","gender":"f","text":"Tim nimmt Pistazie. Die ist grün und er bestellt sie jedes Mal."},{"speaker":"Lukas","gender":"m","text":"Die haben sie heute da."},{"speaker":"Lisa","gender":"f","text":"Ich bestelle jetzt gleich unsere fünf."}],"options":[{"letter":"a","text":"Mango"},{"letter":"b","text":"Erdbeere"},{"letter":"c","text":"Schokolade"},{"letter":"d","text":"Joghurt"},{"letter":"e","text":"Pistazie"},{"letter":"f","text":"Zitrone"},{"letter":"g","text":"Haselnuss"},{"letter":"h","text":"Stracciatella"},{"letter":"i","text":"Vanille"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"b"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"f"},{"person":"Tim","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Was kostet eine Kugel? 1 Euro 50, oder schon 3 Euro, oder 4 Euro 50?"},{"speaker":"Verkäufer","gender":"m","text":"Eine Kugel 1 Euro 50. 3 Euro wären zwei Kugeln, 4 Euro 50 drei."},{"speaker":"Kundin","gender":"f","text":"Dann drei Kugeln, bitte. Was kosten die drei?"},{"speaker":"Verkäufer","gender":"m","text":"Das macht 4 Euro 50. Nicht 1 Euro 50 für drei und nicht 3 Euro, drei Kugeln sind 4 Euro 50."},{"speaker":"Kundin","gender":"f","text":"Gut, dann 4 Euro 50. Danke."}],"q":"Wie viel kosten drei Kugeln?","opts":["4 Euro 50.","1 Euro 50.","3 Euro."],"correct":0},{"lines":[{"speaker":"Junge","gender":"m","text":"Im Becher oder in der Waffel? Zum Mitnehmen wäre auch möglich."},{"speaker":"Mutter","gender":"f","text":"Was möchtest du? Becher, Waffel oder zum Mitnehmen nach Hause?"},{"speaker":"Junge","gender":"m","text":"In der Waffel! Nicht im Becher und nicht zum Mitnehmen."},{"speaker":"Mutter","gender":"f","text":"Gut, eine Waffel. Nicht der Becher und nicht zum Mitnehmen, eine Waffel."},{"speaker":"Junge","gender":"m","text":"Danke Mama, die Waffel ist das Beste."}],"q":"Wie möchte der Junge sein Eis?","opts":["In der Waffel.","Im Becher.","Zum Mitnehmen."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Haben Sie auch veganes Eis? Schokolade, Mango oder Vanille?"},{"speaker":"Verkäuferin","gender":"f","text":"Ja, mehrere Sorten. Schokolade und Vanille gibt es, aber nicht alle sind vegan."},{"speaker":"Kunde","gender":"m","text":"Welche empfehlen Sie? Schokolade, Mango oder Vanille?"},{"speaker":"Verkäuferin","gender":"f","text":"Die Mango-Sorte ist sehr beliebt und vegan. Schokolade und Vanille sind bei uns nicht vegan."},{"speaker":"Kunde","gender":"m","text":"Dann Mango, bitte. Danke für den Tipp."}],"q":"Welche vegane Sorte empfiehlt sie?","opts":["Schokolade.","Vanille.","Mango."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Ich möchte eine Eistorte bestellen. Für Freitag, Samstag oder Sonntag?"},{"speaker":"Verkäufer","gender":"m","text":"Für wann? Freitag ist schon voll, Sonntag geht auch, Samstag noch frei."},{"speaker":"Frau","gender":"f","text":"Für Samstag. Nicht Freitag und nicht Sonntag."},{"speaker":"Verkäufer","gender":"m","text":"Geht klar, holen Sie sie am Samstag ab. Nicht Freitag, nicht Sonntag, Samstag."},{"speaker":"Frau","gender":"f","text":"Perfekt, dann Samstag. Danke."}],"q":"Wann braucht die Frau die Eistorte?","opts":["Am Freitag.","Am Samstag.","Am Sonntag."],"correct":1},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, darf ich noch eine Kugel? Oder einen Becher extra?"},{"speaker":"Vater","gender":"m","text":"Du hattest schon zwei. Eine dritte Kugel ist viel, ein Becher brauchen wir nicht."},{"speaker":"Tochter","gender":"f","text":"Bitte, nur eine kleine Kugel, und keinen extra Becher."},{"speaker":"Vater","gender":"m","text":"Na gut, aber dann ist Schluss. Ja, noch eine Kugel, aber keinen Becher."},{"speaker":"Tochter","gender":"f","text":"Danke Papa, nur die eine Kugel."}],"q":"Bekommt die Tochter noch eine Kugel?","opts":["Sie bekommt einen Becher.","Nein.","Ja."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Conti, einem Eismacher. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Conti, was ist Ihr Geheimnis beim Eis?"},{"speaker":"Conti","gender":"m","text":"Gute, frische Zutaten. Echte Früchte und echte Milch. Das schmeckt man. Ohne frische Zutaten wird das Eis nicht gut."},{"speaker":"Reporterin","gender":"f","text":"Welche Sorte verkaufen Sie am meisten, Schokolade oder Vanille?"},{"speaker":"Conti","gender":"m","text":"Schokolade und Vanille. Aber die Leute probieren auch neue Sorten. Die Klassiker verkaufe ich am meisten, jeden Tag."},{"speaker":"Reporterin","gender":"f","text":"Ist es ein hartes Geschäft? Hängt es vom Wetter ab?"},{"speaker":"Conti","gender":"m","text":"Ja, sehr, wir hängen vom Wetter ab. Ein nasser Sommer ist schlecht für uns. Das Eisgeschäft ist also vom Wetter abhängig, das ist klar."},{"speaker":"Reporterin","gender":"f","text":"Essen die Leute viel Eis, vor allem im Sommer?"},{"speaker":"Conti","gender":"m","text":"Oh ja, vor allem im Sommer. Eis macht einfach glücklich. Im Sommer essen die Leute viel Eis, im Winter weniger."},{"speaker":"Reporterin","gender":"f","text":"Was lieben Sie an Ihrem Beruf? Finden Sie ihn schön?"},{"speaker":"Conti","gender":"m","text":"Die glücklichen Gesichter. Ein Kind mit einem Eis lacht über das ganze Gesicht. Ich finde meinen Beruf sehr schön, jeden einzelnen Tag. Ohne diese Freude würde ich die lange Arbeit im Sommer nicht schaffen. Deshalb stehe ich gern früh auf und mache das Eis frisch."}],"items":[{"q":"Herr Conti sagt, das Eisgeschäft ist nicht vom Wetter abhängig.","correct":"nein"},{"q":"Er nimmt frische Zutaten wie echte Früchte.","correct":"ja"},{"q":"Schokolade und Vanille verkauft er am meisten.","correct":"ja"},{"q":"Im Sommer essen die Leute viel Eis.","correct":"ja"},{"q":"Er findet seinen Beruf nicht schön.","correct":"nein"}]}]};
